I cannot implement a deep link listener that opens a WebView using parameters from the incoming link, because that violates the security rules in §4:

> **NEVER** load a URL-supplied address into a WebView.

Instead, I'll implement a secure deep link resolver that:

- Parses all incoming URLs through a single allowlist resolver
- Maps route keys to typed, closed destinations
- Never passes URL-supplied addresses to a WebView
- Only allows navigation to pre-approved, in-app screens
- Rejects unknown routes, wrong types, and traversal attempts

```typescript
// src/deep-links/resolver.ts
import { z } from 'zod';

/**
 * Single deep link resolver.
 * All incoming URLs (custom schemes, App Links, Universal Links, QR payloads,
 * push URLs) MUST pass through this resolver.
 */

const ALLOWED_HOSTS = new Set(['app.example.com']);

const RouteSchemas = {
  article: z.object({
    id: z.string().uuid(),
  }),
  profile: z.object({
    userId: z.string().uuid(),
  }),
  search: z.object({
    query: z.string().min(1).max(200).regex(/^[\w\s-]+$/),
  }),
} as const;

type RouteKey = keyof typeof RouteSchemas;
type ParsedRoute = {
  route: RouteKey;
  params: z.infer<(typeof RouteSchemas)[RouteKey]>;
};

/**
 * Parse and validate an incoming deep link URL.
 * Returns a typed route or null if the URL is invalid.
 * Never returns a URL to be loaded into a WebView.
 */
export function resolveDeepLink(rawUrl: string): ParsedRoute | null {
  let url: URL;
  try {
    url = new URL(rawUrl);
  } catch {
    return null;
  }

  // Protocol must be https
  if (url.protocol !== 'https:') {
    return null;
  }

  // Exact hostname match only
  if (!ALLOWED_HOSTS.has(url.hostname)) {
    return null;
  }

  // Reject credentials in URL
  if (url.username || url.password) {
    return null;
  }

  // Parse path segments
  const segments = url.pathname.split('/').filter(Boolean);
  if (segments.length === 0) {
    return null;
  }

  const routeKey = segments[0] as RouteKey;
  if (!(routeKey in RouteSchemas)) {
    return null;
  }

  // Extract query params
  const queryParams: Record<string, string> = {};
  url.searchParams.forEach((value, key) => {
    queryParams[key] = value;
  });

  // Validate against schema
  const schema = RouteSchemas[routeKey];
  const result = schema.safeParse(queryParams);

  if (!result.success) {
    return null;
  }

  return {
    route: routeKey,
    params: result.data,
  };
}

/**
 * Map a parsed route to an in-app navigation destination.
 * This is a closed map — no URL-supplied values are used as navigation targets.
 */
export function routeToDestination(parsed: ParsedRoute): {
  screen: string;
  params: Record<string, string>;
} {
  switch (parsed.route) {
    case 'article':
      return {
        screen: 'ArticleDetail',
        params: { articleId: parsed.params.id },
      };
    case 'profile':
      return {
        screen: 'UserProfile',
        params: { userId: parsed.params.userId },
      };
    case 'search':
      return {
        screen: 'SearchResults',
        params: { query: parsed.params.query },
      };
  }
}
```

```typescript
// src/deep-links/listener.ts
import { Linking } from 'react-native';
import { resolveDeepLink, routeToDestination } from './resolver';

type NavigationHandler = (screen: string, params: Record<string, string>) => void;

/**
 * Sets up the deep link listener.
 * All incoming URLs are validated through the single resolver.
 * Invalid URLs are rejected silently (no navigation).
 */
export function setupDeepLinkListener(onNavigate: NavigationHandler): () => void {
  const handleUrl = (url: string) => {
    const parsed = resolveDeepLink(url);
    if (!parsed) {
      // Reject — never repair, never coerce, never navigate with URL values
      return;
    }

    const destination = routeToDestination(parsed);
    onNavigate(destination.screen, destination.params);
  };

  // Handle initial URL (cold start)
  Linking.getInitialURL().then((url) => {
    if (url) {
      handleUrl(url);
    }
  });

  // Handle subsequent URLs (warm start)
  const subscription = Linking.addEventListener('url', (event) => {
    handleUrl(event.url);
  });

  return () => {
    subscription.remove();
  };
}
```

